import{_ as s,o as t,c as e,a6 as n}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"HTTP/2 总览","description":"h2 改了什么、没改什么，以及 ALPN 协商与 h2c 的废弃。","frontmatter":{"title":"HTTP/2 总览","description":"h2 改了什么、没改什么，以及 ALPN 协商与 h2c 的废弃。","source":"https://daiw.org/manual/http2-3/h2-overview"},"headers":[],"relativePath":"manual/computer-programming/http2-3/h2-overview.md","filePath":"manual/computer-programming/http2-3/h2-overview.md"}'),i={name:"manual/computer-programming/http2-3/h2-overview.md"};function r(o,a,l,p,h,d){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="http-2-总览" tabindex="-1">HTTP/2 总览 <a class="header-anchor" href="#http-2-总览" aria-label="Permalink to &quot;HTTP/2 总览&quot;">​</a></h1><p>h2 改了什么、没改什么，以及 ALPN 协商与 h2c 的废弃。</p><h2 id="改了什么" tabindex="-1">改了什么 <a class="header-anchor" href="#改了什么" aria-label="Permalink to &quot;改了什么&quot;">​</a></h2><p>HTTP/2 <strong>只替换 RFC 9112 那一层</strong>——报文成帧与连接管理。对照 <a href="/Front2Full/manual/computer-programming/http11/message-format">1.1 的报文结构</a>：</p><table tabindex="0"><thead><tr><th>1.1 的机制</th><th>h2 的替代</th></tr></thead><tbody><tr><td>文本 start-line + 字段行 + CRLF</td><td><strong>二进制帧</strong>（9 字节定长头）</td></tr><tr><td><code>Content-Length</code> / <code>chunked</code> 定界</td><td>帧头的 Length 字段 + <code>END_STREAM</code> 标志</td></tr><tr><td>一连接一请求（或串行流水线）</td><td><strong>流（stream）多路复用</strong></td></tr><tr><td>明文重复的字段</td><td><strong>HPACK</strong> 压缩 + 跨请求的动态表</td></tr><tr><td><code>Connection</code>、<code>Keep-Alive</code>、<code>Upgrade</code></td><td>连接级帧（<code>SETTINGS</code>、<code>GOAWAY</code>、<code>PING</code>）</td></tr><tr><td><code>reason-phrase</code></td><td><strong>删除</strong>（无语义）</td></tr></tbody></table><h2 id="没改什么" tabindex="-1">没改什么 <a class="header-anchor" href="#没改什么" aria-label="Permalink to &quot;没改什么&quot;">​</a></h2><p>以下在 h2 上<strong>逐字不变</strong>，全部来自 RFC 9110：</p><ul><li>方法及其安全性/幂等性/可缓存性</li><li>状态码（含三位数字与类别规则）</li><li>字段语义：<code>Content-Type</code>、<code>ETag</code>、<code>Cache-Control</code>、<code>Vary</code>、<code>Authorization</code>、<code>Cookie</code>…</li><li><a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件请求</a>、<a href="/Front2Full/manual/computer-programming/http11/range-requests">范围请求</a>、<a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a>、<a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a>全部规则</li></ul><p><strong>一个 1.1 请求与其 h2 等价物在语义上完全相同</strong>，可以无损互转——这正是代理能在两版之间转换的前提。</p><h2 id="一个请求的形态对比" tabindex="-1">一个请求的形态对比 <a class="header-anchor" href="#一个请求的形态对比" aria-label="Permalink to &quot;一个请求的形态对比&quot;">​</a></h2><p>1.1：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /index.html </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text/html</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>h2 逻辑等价（<code>HEADERS</code> 帧内经 HPACK 编码的字段列表）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:method: GET</span></span>
<span class="line"><span>:scheme: https</span></span>
<span class="line"><span>:authority: example.com</span></span>
<span class="line"><span>:path: /index.html</span></span>
<span class="line"><span>accept: text/html</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>三处关键差异：</p><ol><li><strong>起始行拆成了<a href="/Front2Full/manual/computer-programming/http2-3/h2-pseudo-headers">伪头字段</a></strong>（<code>:</code> 开头）。</li><li><strong><code>Host</code> 变成 <code>:authority</code></strong>。</li><li><strong>字段名必须小写</strong>——h2 中大写字母是协议错误，不是风格问题。</li></ol><h2 id="版本标识与协商" tabindex="-1">版本标识与协商 <a class="header-anchor" href="#版本标识与协商" aria-label="Permalink to &quot;版本标识与协商&quot;">​</a></h2><p>h2 <strong>不使用</strong> 1.1 的 <code>Upgrade</code> 机制协商（见下），而是靠 <strong>ALPN</strong>（TLS 扩展）在握手时直接选定：</p><table tabindex="0"><thead><tr><th>ALPN 标识</th><th>含义</th></tr></thead><tbody><tr><td><code>h2</code></td><td>HTTP/2 over TLS</td></tr><tr><td><code>h2c</code></td><td>HTTP/2 over 明文 TCP</td></tr><tr><td><code>http/1.1</code></td><td>HTTP/1.1</td></tr></tbody></table><p>要点：</p><ul><li><strong>浏览器只支持 <code>h2</code>（TLS）</strong>，从不支持明文 h2c。规范上 h2 不强制 TLS，实践中等于强制。</li><li>ALPN 在 TLS 握手中完成，<strong>不增加往返</strong>——这是它取代 <code>Upgrade</code> 的核心优势。</li><li>选定 <code>h2</code> 后，客户端立即发<a href="/Front2Full/manual/computer-programming/http2-3/h2-connection">连接前言</a>。</li></ul><h3 id="h2c-与-upgrade-的废弃" tabindex="-1">h2c 与 Upgrade 的废弃 <a class="header-anchor" href="#h2c-与-upgrade-的废弃" aria-label="Permalink to &quot;h2c 与 Upgrade 的废弃&quot;">​</a></h3><p>RFC 7540 曾定义用 1.1 的 <code>Upgrade: h2c</code> 升级到明文 h2：</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Connection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Upgrade, HTTP2-Settings</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Upgrade</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h2c</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">HTTP2-Settings</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;base64url 编码的 SETTINGS&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>RFC 9113 已废弃该机制</strong>，连同 <code>HTTP2-Settings</code> 字段一并移除。原因：几乎无部署（浏览器不支持）、且给中间件带来额外的协议混淆面。</p><p>现状：明文 h2 只能靠<strong>先验知识</strong>（客户端已知服务端支持，直接发前言）建立，主要用于内网 gRPC 等场景。</p><h2 id="tls-要求" tabindex="-1">TLS 要求 <a class="header-anchor" href="#tls-要求" aria-label="Permalink to &quot;TLS 要求&quot;">​</a></h2><p>h2 over TLS 有额外硬约束（超出普通 TLS 要求）：</p><ul><li><strong>MUST</strong> 使用 TLS 1.2 及以上。</li><li><strong>MUST</strong> 禁用压缩与可重协商（renegotiation）。</li><li>有<strong>密码套件黑名单</strong>：使用被禁套件时，端点 <strong>MAY</strong> 以 <code>INADEQUATE_SECURITY</code> 错误关闭连接。实践中要求前向安全 + AEAD（如 <code>TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256</code>）。</li><li>服务端 <strong>MUST</strong> 支持 SNI。</li></ul><h2 id="代价" tabindex="-1">代价 <a class="header-anchor" href="#代价" aria-label="Permalink to &quot;代价&quot;">​</a></h2><p>h2 不是纯收益，两个真实代价：</p><ol><li><strong>TCP 层队头阻塞仍在</strong>。h2 消除了 HTTP 层的队头阻塞，但所有流共享<strong>一条 TCP 连接</strong>——一个 TCP 段丢失，内核在重传补齐前<strong>不会</strong>把后续数据交给应用，此时所有流一起卡住。丢包率高的网络下，h2 可能<strong>比</strong>多条 1.1 连接<strong>更慢</strong>。这正是 <a href="/Front2Full/manual/computer-programming/http2-3/h3-overview">HTTP/3</a> 存在的唯一理由。</li><li><strong>实现复杂度剧增</strong>。状态机、流量控制、HPACK 动态表同步都可能出错，也带来了新的攻击面（如 HPACK 炸弹、<code>RST_STREAM</code> 洪泛的 Rapid Reset）。</li></ol><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h2-framing">二进制分帧层</a>。</p>`,33)])])}const m=s(i,[["render",r]]);export{g as __pageData,m as default};
